import React, { useState, useEffect } from 'react';
import '../styles/RecommendationWidget.css';

export function RecommendationWidget({ userId, maxItems = 5, onAddToCart }) {
  const [recommendations, setRecommendations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!userId) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    fetch(`http://localhost:5000/api/recommendations/${userId}?limit=${maxItems}`)
      .then(res => {
        if (!res.ok) throw new Error('Failed to fetch recommendations');
        return res.json();
      })
      .then(data => {
        setRecommendations(data.recommendations || []);
        setLoading(false);
      })
      .catch(err => {
        console.error('Recommendation error:', err);
        setError(err.message);
        setLoading(false);
      });
  }, [userId, maxItems]);

  if (!userId) return null;
  if (loading) return <div className="recommendation-loading">Loading recommendations...</div>;
  if (error) return <div className="recommendation-error">Could not load recommendations</div>;
  if (recommendations.length === 0) return null;

  const handleAddToCart = (product) => {
    if (onAddToCart) {
      onAddToCart(product);
    } else {
      // Fallback: store in localStorage
      const cart = JSON.parse(localStorage.getItem('cart') || '[]');
      const existing = cart.find(item => item._id === product._id);
      
      if (existing) {
        existing.quantity = (existing.quantity || 1) + 1;
      } else {
        cart.push({
          _id: product._id,
          name: product.name,
          price: product.price,
          quantity: 1
        });
      }
      
      localStorage.setItem('cart', JSON.stringify(cart));
    }
    alert(`${product.name} added to cart!`);
  };

  return (
    <div className="recommendation-widget">
      <h3>🎯 Recommended for You</h3>
      <div className="recommendation-list">
        {recommendations.map((product, index) => (
          <div key={product._id} className="recommendation-item">
            <div className="recommendation-rank">#{index + 1}</div>
            
            {product.imageUrl && product.imageUrl.length > 0 && (
              <img 
                src={product.imageUrl[0]} 
                alt={product.name}
                className="recommendation-image"
                onError={(e) => {
                  e.target.src = 'https://via.placeholder.com/150?text=Product';
                }}
              />
            )}
            
            <div className="recommendation-content">
              <h4 className="recommendation-name">{product.name}</h4>
              <p className="recommendation-brand">{product.brand}</p>
              <p className="recommendation-category">{product.category}</p>
              
              <div className="recommendation-price-rating">
                <span className="recommendation-price">${product.price}</span>
                <span className="recommendation-rating">
                  ⭐ {(product.rating || 0).toFixed(1)} 
                </span>
              </div>

              <div className="recommendation-scores">
                <small>Match: {(product.finalScore * 100).toFixed(0)}%</small>
              </div>

              <button 
                className="recommendation-btn"
                onClick={() => handleAddToCart(product)}
              >
                Add to Cart
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default RecommendationWidget;
